def _digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"),
                                     ensure_ascii=False).encode()).hexdigest()


def _apply(check_id, original, kind):
    row = ROWS.get(check_id)
    if row is None:
        return deepcopy(original)
    if _digest(original) != row[kind + "_base_sha256"]:
        raise ValueError("Reviewed Azure finding clarity base changed: " + check_id + " (" + kind + ")")
    if kind == "remediation" and row.get("new_text_only_template"):
        # Discard all pending commands/IaC and metadata rather than promoting them.
        current = {}
    elif isinstance(original, dict):
        current = deepcopy(original)
    else:
        raise ValueError("Reviewed Azure finding clarity base type changed: " + check_id)
    from .azure_native_review_copy_20261020 import reviewed_fields
    current.update(reviewed_fields(check_id, kind, row[kind + "_fields"]))
    return current


def description(check_id, original):
    return _apply(check_id, original, "description")


def remediation(check_id, original):
    return _apply(check_id, original, "remediation")
